def _signature(tree):
    return frozenset((s.in_out,s.name,s.socket_type) for s in tree.interface.items_tree
                     if s.item_type=='SOCKET')


def direct_records(original):
    if not original.get('st_initial_samples_only'):
        raise ValueError('Direct records need a qualified initial-only cyclic source')
    name=original.name
    if 'Ordinary cyclic direct quad layout' not in name:
        raise ValueError('Unknown initial-only layout: '+name)
    dependencies={}
    for node in original.nodes:
        if node.type=='GROUP' and node.node_tree:
            dependencies.setdefault(_signature(node.node_tree),set()).add(node.node_tree)
    generated=cyclic.build(compound=False,continuations='Curb continuations' in name,
        port_paths=True,span_compounds='Original span sides' in name,
        chain_sides='Original chain sides' in name,coarse_seed=False,
        interpolation='Exact entrance rays' in name,initial_samples_only=True,
        direct_corner_source=True)
    result=generated.copy()
    result.name='Prochitecture Streets / Direct corner source / '+hashlib.sha256(name.encode()).hexdigest()[:16]
    known=_signature(result)
    for socket in original.interface.items_tree:
        if socket.item_type!='SOCKET' or (socket.in_out,socket.name,socket.socket_type) in known:continue
        if socket.in_out!='INPUT':raise ValueError('Unknown source output: '+socket.name)
        added=result.interface.new_socket(name=socket.name,in_out='INPUT',socket_type=socket.socket_type)
        if hasattr(socket,'default_value'):added.default_value=socket.default_value
    inp,=[n for n in result.nodes if n.type=='GROUP_INPUT']
    reused=set()
    for node in result.nodes:
        if node.type!='GROUP' or not node.node_tree:continue
        required=_signature(node.node_tree)
        matches=set().union(*(trees for signature,trees in dependencies.items()
                             if required<=signature and all(item[0]=='INPUT' for item in signature-required)))
        if len(matches)!=1:
            raise ValueError('Ambiguous or missing original source program: '+node.node_tree.name)
        saved,=matches
        if any(s.name=='v' and s.in_out=='INPUT' for s in saved.interface.items_tree if s.item_type=='SOCKET'):
            cyclic._prove_transverse_range_only(saved)
        assign_group(node,saved);reused.add(saved.name)
        # Reserved station programs add Corners/Mouths and a bounded Blend.
        # Preserve the saved bindings rather than replacing their policy.
        callers=[n for n in original.nodes if n.type=='GROUP' and n.node_tree==saved]
        for direction,key,kind in _signature(saved)-required:
            bindings=set()
            for caller in callers:
                socket=caller.inputs[key]
                if socket.is_linked:
                    link,=socket.links
                    if link.from_node.type!='GROUP_INPUT':
                        raise ValueError('Unsupported extra source-program binding: '+key)
                    bindings.add(('input',link.from_socket.name))
                else:bindings.add(('literal',socket.default_value))
            if len(bindings)!=1:raise ValueError('Source-program bindings disagree: '+key)
            binding,value=bindings.pop()
            if binding=='input':result.links.new(inp.outputs[value],node.inputs[key])
            else:node.inputs[key].default_value=value
    return result,dict(original=original.name,replacement=result.name,
                       reused_programs=sorted(reused),preliminary_center_built=False)


def perimeter_records(original):
    """Replace a disposable full grid with its ordered perimeter records.

    The local-pattern source is point lookup data, never a pavement. Preserve
    every row-major source index and all chart/identity-weld checks. Removing
    its temporary edges changes no point query; final quads are built elsewhere.
    """
    if not original.get('st_direct_corner_records'):
        raise ValueError('Linear records require the qualified direct corner source')
    result=original.copy()
    result.name='Prochitecture Streets / Linear corner source / '+hashlib.sha256(original.name.encode()).hexdigest()[:16]
    g=cyclic.c.Graph.__new__(cyclic.c.Graph);g.g=result;g.count=len(result.nodes);g.frame=None
    grids=[n for n in result.nodes if n.bl_idname=='GeometryNodeMeshGrid']
    if len(grids)!=1 or grids[0].label!='Direct regular half-profile band':
        raise ValueError('Unrecognized direct-record grid')
    grid,=grids
    consumer,=grid.outputs['Mesh'].links
    store=consumer.to_node
    if (store.bl_idname!='GeometryNodeStoreNamedAttribute' or store.domain!='POINT' or
            store.data_type!='INT' or store.inputs['Name'].default_value!='_cq_source_index'):
        raise ValueError('Grid no longer feeds its row-major point identity')
    value,=store.inputs['Value'].links
    if value.from_node.bl_idname!='GeometryNodeInputIndex':
        raise ValueError('Unexpected original grid-index mapping')
    dimensions=[]
    for key in ('Vertices X','Vertices Y'):
        link,=grid.inputs[key].links
        dimensions.append(cyclic.c.V(g,link.from_socket))
    columns_x,columns_y=dimensions
    # The saved grid uses row=floor(index/(nv+1)), col=index mod (nv+1).
    nu,nv=columns_x-1.,columns_y-1.
    index=cyclic.c.V(g,value.from_socket)
    middle=index-(nv+1.)
    end_start=nv+1.+2.*(nu-1.)
    middle_source=(g.math('FLOOR',middle*.5)+1.)*(nv+1.)+g.math('MODULO',middle,2.)*nv
    source=cyclic.c.choose(g,g.math('LESS_THAN',index,nv+1.),index,
        cyclic.c.choose(g,g.math('LESS_THAN',index,end_start),middle_source,
                        nu*(nv+1.)+index-end_start))
    records=cyclic.c._line(g,2.*(nu+nv))
    delete=g.node('GeometryNodeDeleteGeometry','Corner lookup records need no temporary edges')
    delete.domain='EDGE';delete.mode='EDGE_FACE'
    delete.inputs['Selection'].default_value=True
    g.bind(records,delete.inputs['Geometry'])
    g.bind(delete.outputs['Geometry'],store.inputs['Geometry'])
    g.bind(source,store.inputs['Value'])
    result.nodes.remove(grid)
    result['st_linear_perimeter_records']=1
    return result,dict(original=original.name,replacement=result.name,
        original_allocation='(nu+1)*(nv+1)',record_allocation='2*(nu+nv)',
        source_index_order='unchanged row-major perimeter',
        guards='unchanged chart range, station, source, and identity-weld checks',
        temporary_topology='isolated lookup points; final surface topology unchanged')


def copy_graph(root, *, linear_perimeter=False):
    """Change only lookup sources under the existing local-pattern adapters."""
    memo,source_memo,changes={},{},[]
    def source(tree):
        if tree in source_memo:return source_memo[tree]
        if tree.get('st_initial_samples_only') and any(n.bl_idname=='GeometryNodeMeshGrid' for n in tree.nodes):
            result,proof=(perimeter_records(tree) if linear_perimeter else direct_records(tree))
            changes.append(proof)
        else:
            replacements=[(n.name,source(n.node_tree)) for n in tree.nodes
                          if n.type=='GROUP' and n.node_tree]
            replacements=[(name,child) for name,child in replacements if child!=tree.nodes[name].node_tree]
            result=tree.copy() if replacements else tree
            for name,child in replacements:assign_group(result.nodes[name],child)
        source_memo[tree]=result
        return result
    def visit(tree):
        if tree in memo:return memo[tree]
        local=any(n.type=='GROUP' and n.label=='Local corner patterns and direct quad center' for n in tree.nodes)
        replacements=[]
        for node in tree.nodes:
            if node.type!='GROUP' or not node.node_tree:continue
            child=(source(node.node_tree) if local and node.label==
                   'Original analytic boundary and ray samples; no interior descent' else visit(node.node_tree))
            if child!=node.node_tree:replacements.append((node.name,child))
        result=tree.copy() if replacements else tree
        for name,child in replacements:assign_group(result.nodes[name],child)
        memo[tree]=result
        return result
    multiple=isinstance(root,(list,tuple))
    result=[visit(tree) for tree in root] if multiple else visit(root)
    if not changes:raise ValueError('No local-pattern initial-only sources found')
    return result,dict(sources=changes,scope='Lookup data only; unchanged complete patch guards and fallbacks')
